function shortestWalk(grid: number[][], k: number): number {
  const m = grid.length, n = grid[0].length;
  const seen = new Uint8Array(m * n * (k + 1));
  const id = (r: number, c: number, left: number) => (r * n + c) * (k + 1) + left;
  let frontier: number[][] = [[0, 0, k]];
  seen[id(0, 0, k)] = 1;
  const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  for (let steps = 0; frontier.length; steps++) {
    const next: number[][] = [];
    for (const [r, c, rem] of frontier) {
      if (r === m - 1 && c === n - 1) return steps;
      for (const [dr, dc] of dirs) {
        const nr = r + dr, nc = c + dc;
        if (nr < 0 || nc < 0 || nr >= m || nc >= n) continue;
        const left = rem - grid[nr][nc];
        if (left < 0 || seen[id(nr, nc, left)]) continue;
        seen[id(nr, nc, left)] = 1;
        next.push([nr, nc, left]);
      }
    }
    frontier = next;
  }
  return -1;
}

