class Solution:
    def shortestWalk(self, grid: List[List[int]], k: int) -> int:
        m, n = len(grid), len(grid[0])
        seen = {(0, 0, k)}
        frontier, steps = [(0, 0, k)], 0
        while frontier:
            nxt = []
            for r, c, rem in frontier:
                if r == m - 1 and c == n - 1:
                    return steps
                for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
                    if 0 <= nr < m and 0 <= nc < n:
                        left = rem - grid[nr][nc]
                        if left >= 0 and (nr, nc, left) not in seen:
                            seen.add((nr, nc, left))
                            nxt.append((nr, nc, left))
            frontier, steps = nxt, steps + 1
        return -1

