function shortestWalk(grid: number[][], k: number): number {
  const m = grid.length, n = grid[0].length;
  if (k >= m + n - 3) return m + n - 2; // smash everything on the straight staircase path
  const best = new Int32Array(m * n).fill(-1);
  best[0] = k;
  let frontier: number[] = [0, 0, k]; // flat triples: r, c, rem
  const dirs = [1, 0, -1, 0, 0, 1, 0, -1];
  for (let steps = 0; frontier.length; steps++) {
    const next: number[] = [];
    for (let i = 0; i < frontier.length; i += 3) {
      const r = frontier[i], c = frontier[i + 1], rem = frontier[i + 2];
      if (r === m - 1 && c === n - 1) return steps;
      for (let d = 0; d < 8; d += 2) {
        const nr = r + dirs[d], nc = c + dirs[d + 1];
        if (nr < 0 || nc < 0 || nr >= m || nc >= n) continue;
        const left = rem - grid[nr][nc];
        if (left <= best[nr * n + nc]) continue; // an earlier arrival had at least as many smashes left
        best[nr * n + nc] = left;
        next.push(nr, nc, left);
      }
    }
    frontier = next;
  }
  return -1;
}

